const Koa = require('koa');
const Router = require('koa-router');
const multer = require('@koa/multer');
const bodyParser = require('koa-bodyparser');
const { exec } = require('child_process');
const fs = require('fs');
const path = require('path');
const util = require('util');

const app = new Koa();
const router = new Router();
const upload = multer({ dest: 'uploads/' });
const execPromise = util.promisify(exec);

router.post('/create-gif', upload.array('images'), async (ctx) => {
  try {
    const files = ctx.files;
    const { targetSize, delay = 10, appendReverted = false } = ctx.request.body;

    if (!files || files.length === 0) {
      ctx.status = 400;
      ctx.body = { error: 'No images uploaded' };
      return;
    }

    if (!targetSize) {
      ctx.status = 400;
      ctx.body = { error: 'Target size is required' };
      return;
    }

    const imagePaths = files.map(file => file.path);
    let command = `convert -delay ${delay} -resize ${targetSize} ${imagePaths.join(' ')} `;

    if (appendReverted === 'true') {
      command += `${imagePaths.reverse().join(' ')} `;
    }

    const outputGif = path.join('uploads', `output-${Date.now()}.gif`);
    command += outputGif;

    await execPromise(command);

    ctx.set('Content-Type', 'image/gif');
    ctx.body = fs.createReadStream(outputGif);

    // Clean up temporary files
    ctx.res.on('finish', () => {
      imagePaths.forEach(filePath => fs.unlink(filePath, () => {}));
      fs.unlink(outputGif, () => {});
    });

  } catch (error) {
    ctx.status = 500;
    ctx.body = { error: 'Internal Server Error' };
  }
});

app
  .use(bodyParser())
  .use(router.routes())
  .use(router.allowedMethods());

app.listen(5000, '0.0.0.0', () => {
  console.log('Server running on http://0.0.0.0:5000');
});
```
